(* ORIG_REF_NAME = "frame_tick" *) 
module system_pattern_hdmi_axi_0_2_frame_tick
   (previous_origin,
    tick_reg_0,
    tick_reg_1,
    tick_reg_2,
    tick_reg_3,
    E,
    at_origin,
    dest_clk,
    dest_arst,
    tick0,
    \ebul_x[9][10]_i_5 ,
    \center_hold_cnt_reg[1] ,
    btn_center_held,
    Q);
  output previous_origin;
  output tick_reg_0;
  output tick_reg_1;
  output tick_reg_2;
  output tick_reg_3;
  output [0:0]E;
  input at_origin;
  input dest_clk;
  input dest_arst;
  input tick0;
  input \ebul_x[9][10]_i_5 ;
  input \center_hold_cnt_reg[1] ;
  input btn_center_held;
  input [0:0]Q;

  wire [0:0]E;
  wire [0:0]Q;
  wire at_origin;
  wire btn_center_held;
  wire \center_hold_cnt_reg[1] ;
  wire dest_arst;
  wire dest_clk;
  wire \ebul_x[9][10]_i_5 ;
  wire previous_origin;
  wire tick0;
  wire tick_reg_0;
  wire tick_reg_1;
  wire tick_reg_2;
  wire tick_reg_3;

  (* SOFT_HLUTNM = "soft_lutpair86" *) 
  LUT2 #(
    .INIT(4'hB)) 
    \center_hold_cnt[6]_i_2 
       (.I0(tick_reg_0),
        .I1(btn_center_held),
        .O(tick_reg_3));
  (* SOFT_HLUTNM = "soft_lutpair85" *) 
  LUT2 #(
    .INIT(4'h2)) 
    \center_hold_cnt[6]_i_4 
       (.I0(tick_reg_0),
        .I1(\center_hold_cnt_reg[1] ),
        .O(tick_reg_2));
  (* SOFT_HLUTNM = "soft_lutpair85" *) 
  LUT2 #(
    .INIT(4'h4)) 
    \ebul_y[8][10]_i_7 
       (.I0(tick_reg_0),
        .I1(\ebul_x[9][10]_i_5 ),
        .O(tick_reg_1));
  FDPE #(
    .INIT(1'b1)) 
    previous_origin_reg
       (.C(dest_clk),
        .CE(1'b1),
        .D(at_origin),
        .PRE(dest_arst),
        .Q(previous_origin));
  (* SOFT_HLUTNM = "soft_lutpair86" *) 
  LUT2 #(
    .INIT(4'h8)) 
    \scroll_med[9]_i_1 
       (.I0(tick_reg_0),
        .I1(Q),
        .O(E));
  FDCE tick_reg
       (.C(dest_clk),
        .CE(1'b1),
        .CLR(dest_arst),
        .D(tick0),
        .Q(tick_reg_0));
endmodule

